// Matrix-style code rain with ON/OFF terminal toggle (default ON, remembers choice)
    (function(){
      const c = document.getElementById('rain');
      const btn = document.getElementById('rainToggle');
      if (!c || !btn) return;

      const labelEl = btn.querySelector('.label');
      const ctx = c.getContext('2d', { alpha:true });

      const glyphs = (
        "アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン" +
        "0123456789" +
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ" +
        "abcdefghijklmnopqrstuvwxyz"
      ).split("");

      let w=0, h=0, cols=0, drops=[];
      let rafId = 0;
      let running = false;

      function resize(){
        const dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
        w = Math.floor(window.innerWidth);
        h = Math.floor(window.innerHeight);
        c.width = Math.floor(w * dpr);
        c.height = Math.floor(h * dpr);
        c.style.width = w + "px";
        c.style.height = h + "px";
        ctx.setTransform(dpr,0,0,dpr,0,0);

        const fontSize = 16;
        cols = Math.max(1, Math.floor(w / fontSize));
        drops = Array.from({length: cols}, () => Math.random() * h / fontSize);

        ctx.font = "700 16px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace";
        ctx.textBaseline = "top";
      }

      function clearCanvas(){ ctx.clearRect(0,0,w,h); }

      let last=0;
      function frame(t){
        if (!running) return;

        // cap to ~40fps for battery friendliness
        if (t - last < 25) { rafId = requestAnimationFrame(frame); return; }
        last = t;

        // fade
        ctx.fillStyle = "rgba(2, 6, 10, 0.12)";
        ctx.fillRect(0,0,w,h);

        const fontSize = 16;
        for (let i=0; i<cols; i++){
          const x = i * fontSize;
          const y = drops[i] * fontSize;

          const ch = glyphs[(Math.random()*glyphs.length)|0];

          // green with occasional blue highlight
          ctx.fillStyle = (Math.random() < 0.03)
            ? "rgba(0, 229, 255, .55)"
            : "rgba(34, 255, 143, .75)";

          ctx.fillText(ch, x, y);

          if (y > h && Math.random() > 0.975) drops[i] = 0;
          drops[i] += 0.85 + Math.random()*0.75;
        }

        rafId = requestAnimationFrame(frame);
      }

      function setButtonState(on){
        btn.classList.toggle('off', !on);
        btn.setAttribute('aria-pressed', String(on));
        if (labelEl) labelEl.textContent = on ? 'RAIN::TRUE' : 'RAIN::FALSE';
      }

      function start(){
        if (running) return;
        c.style.display = "block";
        resize();
        running = true;
        rafId = requestAnimationFrame(frame);
      }

      function stop(){
        running = false;
        if (rafId) cancelAnimationFrame(rafId);
        rafId = 0;
        c.style.display = "none";
        clearCanvas();
      }

      function setEnabled(on){
        localStorage.setItem('matrixRainEnabled', on ? '1' : '0');
        if (on) start(); else stop();
        setButtonState(on);
      }

      // Default ON unless user previously turned it OFF
      const saved = localStorage.getItem('matrixRainEnabled');
      const enabled = (saved === null) ? true : (saved === '1');

      btn.addEventListener('click', () => setEnabled(!running));
      window.addEventListener('resize', () => { if (running) resize(); }, {passive:true});

      setButtonState(enabled);
      if (enabled) start(); else stop();
    })();
